#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;

int main() {
    int d, m, n, p;
    int sm;

    vector<int> a;

    while (scanf("%d", &d) && d) {
        scanf("%d %d", &m, &n);
        a.clear();
        a.push_back(0);

        for (int i = 0; i < m - 1; i++) {
            int c;
            scanf("%d", &c);
            a.push_back(c);
        }

        a.push_back(d);
        sort(a.begin(), a.end());
        sm = 0;

        for (int i = 0; i < n; i++) {
            scanf("%d", &p);
            // Using binary search to find the closest boundaries in vector a
            auto it = lower_bound(a.begin(), a.end(), p);
            int j = it - a.begin();

            sm += min(p - a[j - 1], a[j] - p);
        }

        printf("%d\n", sm);
    }

    return 0;
}

